mapper.select:
SELECT /* homes.buld.mapper.BuldMapper.isUpdatePpsCd 용도변경 조회 */
       CASE WHEN A.MAIN_PPS_CD = #{ppscd} THEN 'N' ELSE 'Y' END AS IS_UPDATED
       , ( SELECT NVL(MAX(HISTNO), 0) + 1 AS HISTNO
           FROM TB_BD_TITLE_LEDGR_PPS_HIST A
           WHERE  A.BULD_REGSTR_PK = #{buldno}
       ) AS HISTNO 
FROM   TB_BD_TITLE_LEDGR_PPS A
WHERE  A.BULD_REGSTR_PK = #{buldno}

mapper.insert:
INSERT /* homes.buld.mapper.BuldMapper.insertLedgrPpscdHist 용도변경이력 등록 */
INTO   TB_BD_TITLE_LEDGR_PPS_HIST (
	   BULD_REGSTR_PK, HISTNO, HISTDE
	   , MAIN_PPS_CD, ETC_PPS
	   , CREAT_USER_NO
	   , UPDT_USER_NO
) 
SELECT BULD_REGSTR_PK
       , #{histno}
       , DATE_FORMAT(NOW(), '%Y%m%d')
       , MAIN_PPS_CD
       , ETC_PPS
       , #{brkno}
       , #{brkno}
FROM   TB_BD_TITLE_LEDGR_PPS
WHERE  BULD_REGSTR_PK = #{buldno}

mapper.update:
UPDATE /* homes.buld.mapper.BuldMapper.updateLedgrPpscd 건물용도 변경 */
TB_BD_TITLE_LEDGR_PPS
SET    UPDT_USER_NO = #{brkno}
       , UPDT_DT = NOW() 

       , MAIN_PPS_CD = #{ppscd}


       , ETC_PPS = #{etcppscd}

WHERE  BULD_REGSTR_PK = #{buldno}
